import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { cloneDeepWith } from "./src/object/cloneDeepWith.js";
import { noop } from "./src/function/noop.js";
{
{
{
const calls = [];
        const obj = { a: 1, b: { c: 2 } };
        cloneDeepWith(obj, (value, key, object, stack) => {
            calls.push({ value, key, object, hasStack: stack instanceof Map });
            return undefined;
        });
        expect(calls[0]).toEqual({
            value: obj,
            key: undefined,
            object: obj,
            hasStack: true,
        });
        expect(calls[1]).toEqual({
            value: 1,
            key: 'a',
            object: obj,
            hasStack: true,
        });
        expect(calls[2]).toEqual({
            value: obj.b,
            key: 'b',
            object: obj,
            hasStack: true,
        });
}
}
}

